// lib
namespace ProjectA
{
    // Dependency-free library type: no MessagePack reference here.
    public class MyType
    {
        public int Id { get; set; }
        public string Name { get; set; }
    }
}

// app
using System;
using ProjectA;

namespace ProjectB
{
    public static class Program
    {
        public static void Main()
        {
            // Old: CS0234/CS0246 - type MessagePack.GeneratedMessagePackFormatterAttribute does not exist.
            // New: compiles, the public attribute type is present.
            Type attributeType = typeof(MessagePack.GeneratedMessagePackFormatterAttribute);
            Attribute instance = (Attribute)Activator.CreateInstance(attributeType);

            var value = new MyType { Id = 1, Name = "a" };
            Console.WriteLine(attributeType.FullName + " " + (instance != null) + " " + value.Name);
        }
    }
}
